arguments.command:
cd /tmp/vally-eval-trial-cOpJaa && cat > src/CheckoutPricing.Application/CalculatePayableTotalHandler.cs <<'E'
namespace CheckoutPricing.Application;

public sealed record CalculatePayableTotalRequest(string CustomerTier, decimal OrderSubtotal);

public sealed class CalculatePayableTotalHandler
{
    public decimal Handle(CalculatePayableTotalRequest request) => request.OrderSubtotal;
}
E
mkdir -p tests/CheckoutPricing.UnitTests/Checkout && cat > tests/CheckoutPricing.UnitTests/Checkout/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Checkout;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void Gold_customer_pays_95_for_a_100_subtotal()
    {
        var handler = new CalculatePayableTotalHandler();

        var payable = handler.Handle(new CalculatePayableTotalRequest("Gold", 100.00m));

        Assert.Equal(95.00m, payable);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | grep -vE "^\s*$" | tail -20

